const types:Record<string,string>={'.html':'text/html','.js':'text/javascript','.mjs':'text/javascript','.css':'text/css','.json':'application/json','.svg':'image/svg+xml','.png':'image/png','.jpg':'image/jpeg','.webp':'image/webp','.wasm':'application/wasm','.mp3':'audio/mpeg','.wav':'audio/wav','.mp4':'video/mp4','.webm':'video/webm'};
const server=createServer((req,res)=>{let p=join(dist,decodeURIComponent((req.url??'/').split('?')[0]));if(existsSync(p)&&statSync(p).isDirectory())p=join(p,'index.html');if(!p.startsWith(dist)||!existsSync(p)){res.statusCode=404;res.end();return;}res.setHeader('Content-Type',types[extname(p)]??'application/octet-stream');res.end(readFileSync(p));});await new Promise<void>(r=>server.listen(4407,'127.0.0.1',r));
const chrome=spawn(chromePath,['--headless=new','--use-angle='+(process.env.ARA_TEST_NATIVE_GPU==='1'?'metal':'swiftshader'),'--enable-unsafe-swiftshader','--no-first-run',`--user-data-dir=${profile}`,'--remote-debugging-pipe','--window-size=1280,900','about:blank'],{stdio:['ignore','ignore','ignore','pipe','pipe']});
const input=chrome.stdio[3]as Writable,output=chrome.stdio[4]as Readable,pending=new Map<number,{resolve:(v:unknown)=>void;reject:(e:Error)=>void}>();let seq=0,session='',buffer='';const errors:string[]=[];
output.on('data',(c:Buffer)=>{buffer+=c.toString();let n;while((n=buffer.indexOf('\0'))>=0){const m=JSON.parse(buffer.slice(0,n));buffer=buffer.slice(n+1);if(m.id){const p=pending.get(m.id);pending.delete(m.id);if(m.error)p?.reject(Error(m.error.message));else p?.resolve(m.result);}else if(m.method==='Runtime.exceptionThrown')errors.push(m.params.exceptionDetails.exception?.description??m.params.exceptionDetails.text);}});
function send<T=Record<string,unknown>>(method:string,params:object={},attach=true):Promise<T>{const id=++seq;return new Promise((resolve,reject)=>{const timeout=setTimeout(()=>{pending.delete(id);reject(Error('Chrome protocol timed out: '+method));},45000);pending.set(id,{resolve:v=>{clearTimeout(timeout);resolve(v as T);},reject:e=>{clearTimeout(timeout);reject(e);}});input.write(JSON.stringify({id,method,params,...(attach&&session?{sessionId:session}:{})})+'\0');});}
async function evaluate<T=unknown>(expression:string):Promise<T>{const r=await send<{result:{value:T};exceptionDetails?:{text:string;exception?:{description:string}}}>('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(r.exceptionDetails)throw Error(r.exceptionDetails.exception?.description??r.exceptionDetails.text);return r.result.value;}
const sleep=(ms:number)=>new Promise(r=>setTimeout(r,ms));
async function wait(expression:string,label:string,ms=30000){const end=Date.now()+ms;while(Date.now()<end){if(await evaluate(expression).catch(()=>false))return;await sleep(100);}throw Error('Timed out: '+label+' '+await evaluate('JSON.stringify(window.araPlay?.game)'));}
async function click(selector:string,touch=false){await evaluate(`(()=>{const b=document.querySelector(${JSON.stringify(selector)}),r=b.getBoundingClientRect();if(b.closest('dialog')&&!b.closest('.setup-actions'))b.scrollIntoView({block:'center'});else if(r.top<0||r.bottom>innerHeight)b.scrollIntoView({block:'nearest'});})()`);await evaluate('new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)))');const p=await evaluate<{x:number;y:number}>(`(()=>{const b=document.querySelector(${JSON.stringify(selector)});const r=b.getBoundingClientRect();return{x:r.x+r.width/2,y:r.y+r.height/2}})()`);if(touch){await send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{...p,id:1}]});await sleep(60);await send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});}else{await send('Input.dispatchMouseEvent',{type:'mousePressed',button:'left',clickCount:1,...p});await send('Input.dispatchMouseEvent',{type:'mouseReleased',button:'left',clickCount:1,...p});}await sleep(120);}
async function key(code:string,down=true){const name=code.startsWith('Key')?code.slice(3).toLowerCase():code==='ShiftLeft'?'Shift':code;await send('Input.dispatchKeyEvent',{type:down?'keyDown':'keyUp',key:name,code});}
async function press(code:string){await key(code);await key(code,false);}
async function travel(code:string,condition:string){await key('ShiftLeft');await key(code);try{await wait(condition,code+' movement',30000);}finally{await key(code,false);await key('ShiftLeft',false);}await sleep(250);}
mkdirSync('out/play',{recursive:true});async function photo(name:string){const r=await send<{data:string}>('Page.captureScreenshot',{format:'png'});writeFileSync('out/play/'+name+'.png',Buffer.from(r.data,'base64'));}
async function keyboardRoute(to:{x:number;z:number},label:string){
 await evaluate('araPlay.scene.azimuth=0');const held=new Set<string>();await key('ShiftLeft');let limit=1400;
 try{while(limit-->0){const state=await evaluate<any>('({player:araPlay.game.player,companion:araPlay.game.companion,car:araPlay.game.car,world:araPlay.game.world,door:araPlay.game.door,status:araPlay.game.status})');if(state.status==='won'&&distance(state.player,to)<2.3)break;assert.equal(state.status,'playing',label);if(distance(state.player,to)<.22)break;
  const rects=obstacles(state.door,state.world.blocks,state.world.gate,state.world.gateWidth);if(state.car)rects.push(carObstacle(state.car));if(state.companion&&!state.companion.riding&&distance(state.companion,to)>1)rects.push(enemyVolume(state.companion));let path=route(state.player,to,rects,state.player.radius+.12,state.world.bounds);if(!path.length)path=route(state.player,to,rects,state.player.radius,state.world.bounds);assert.ok(path.length,label+' has a reachable route');let target=path[0];if(path.length>1&&distance(state.player,target)<.25)target=path[1];const dx=target.x-state.player.x,dz=target.z-state.player.z,length=Math.hypot(dx,dz),wanted=new Set<string>();if(Math.abs(dx)/length>.12)wanted.add(dx>0?'KeyD':'KeyA');if(Math.abs(dz)/length>.12)wanted.add(dz>0?'KeyS':'KeyW');for(const code of held)if(!wanted.has(code)){await key(code,false);held.delete(code);}for(const code of wanted)if(!held.has(code)){await key(code);held.add(code);}await sleep(65);
 }}finally{for(const code of held)await key(code,false);await key('ShiftLeft',false);}assert.ok(await evaluate(`(Math.hypot(araPlay.game.player.x-(${to.x}),araPlay.game.player.z-(${to.z}))<.5||araPlay.game.status==="won"&&Math.hypot(araPlay.game.player.x-(${to.x}),araPlay.game.player.z-(${to.z}))<2.3)`),label+' reached: '+await evaluate('JSON.stringify({x:araPlay.game.player.x,z:araPlay.game.player.z,status:araPlay.game.status})'));await sleep(200);
}
async function rescuePickupLoop(prefix:string){
 await evaluate('araPlay.game.enemies.forEach(e=>e.combat.health=0)');await keyboardRoute(await evaluate<any>('araPlay.game.world.rescue.approach'),'captive');await press('KeyE');await wait('araPlay.game.companion.rescued&&!araPlay.game.action','companion freed');assert.equal(await evaluate('araPlay.game.checkpoint.stage'),'rescue');
 await keyboardRoute(driverStand(await evaluate<any>('araPlay.game.car')),'pickup driver door');await press('KeyE');await wait('araPlay.game.companion.riding?.phase==="boarding"','passenger actually boards',45000);await press('Escape');const snapshot=await evaluate('JSON.stringify(araPlay.game.companion.riding)');await sleep(250);assert.equal(await evaluate('JSON.stringify(araPlay.game.companion.riding)'),snapshot);await evaluate('document.getElementById("paused").hidden=true;araPlay.scene.azimuth=-1.2;araPlay.scene.zoom=6');await photo(prefix+'-boarding');await press('Escape');await wait('araPlay.game.readyToDrive&&araPlay.game.companion.riding?.phase==="seated"','both seated',45000);assert.equal(await evaluate('araPlay.game.checkpoint.stage'),'vehicle');await photo(prefix+'-both-seated');
 await press('KeyE');await wait('araPlay.game.car.phase==="parked"&&!araPlay.game.companion.riding','both alight');await photo(prefix+'-both-alighted');await press('KeyE');await wait('araPlay.game.readyToDrive','both reboard');await key('KeyW');try{await wait('Math.abs(araPlay.game.car.z-araPlay.game.world.exit.z)<araPlay.game.car.speed**2/22+1','rescue stopping distance');}finally{await key('KeyW',false);}await key('Space');try{await wait('araPlay.game.status==="won"','rescue pickup extraction');}finally{await key('Space',false);}assert.ok(await evaluate('araPlay.game.objectivesCompleted===3&&araPlay.game.companion.combat.health>0&&araPlay.game.companion.riding.phase==="seated"'));await photo(prefix+'-complete');
}
async function openProjectFile(value:unknown,name:string){const file=join(profile,name+'.json');writeFileSync(file,JSON.stringify(value));await click('#open-project');const dom=await send<{root:{nodeId:number}}>('DOM.getDocument');const {nodeId}=await send<{nodeId:number}>('DOM.querySelector',{nodeId:dom.root.nodeId,selector:'#file'});await send('DOM.setFileInputFiles',{nodeId,files:[file]});await wait('document.getElementById("game-title").value==="Cargo Run"','campaign file opens');}
async function driveCourseKeyboard(prefix:string){await evaluate('araPlay.scene.renderer.setPixelRatio(.6)');const path=await evaluate<{x:number;z:number}[]>('araPlay.game.world.getaway.route');let index=0,limit=4500,lastStage=-1;const held=new Set<string>();
 try{while(limit-->0){const s=await evaluate<any>('({car:{x:araPlay.game.car.x,z:araPlay.game.car.z,yaw:araPlay.game.car.yaw,speed:araPlay.game.car.speed},status:araPlay.game.status,exit:araPlay.game.world.exit,stage:araPlay.game.routeStage})');if(s.status!=='playing')break;while(index<path.length-1&&distance(s.car,path[index])<4)index++;let target=path[index];for(let j=index;j<path.length;j++)if(distance(s.car,path[j])>5.5){target=path[j];break;}const yaw=Math.atan2(target.x-s.car.x,target.z-s.car.z),angle=Math.atan2(Math.sin(yaw-s.car.yaw),Math.cos(yaw-s.car.yaw)),d=distance(s.car,s.exit),wanted=new Set<string>();if(d<s.car.speed*s.car.speed/22+1)wanted.add('Space');else if(s.car.speed<4.5)wanted.add('KeyW');if(angle>.045)wanted.add('KeyA');if(angle<-.045)wanted.add('KeyD');if(Math.abs(angle)>.4&&s.car.speed>3)wanted.add('Space');for(const c of held)if(!wanted.has(c)){await key(c,false);held.delete(c);}for(const c of wanted)if(!held.has(c)){await key(c);held.add(c);}if(s.stage>lastStage){lastStage=s.stage;await photo(prefix+'-road-'+s.stage);}await sleep(65);}
 }finally{for(const c of held)await key(c,false);await evaluate('araPlay.scene.renderer.setPixelRatio(1)');}assert.equal(await evaluate('araPlay.game.status'),'won','complete road course: '+await evaluate('JSON.stringify({car:araPlay.game.car,stage:araPlay.game.routeStage})'));
}
async function campaignMobile(){await send('Emulation.setTouchEmulationEnabled',{enabled:true});for(const [width,height]of [[320,568],[844,390]]){await send('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile:true});await evaluate('araPlay.game.events.push({time:araPlay.game.time+.0001,type:"hint",text:"Find the brass key in the west yard."})');await wait('document.getElementById("announcement").textContent.includes("Find the brass key")','visible instruction for mobile clearance');await sleep(200);assert.ok(await evaluate('(()=>{const a=document.getElementById("objective").getBoundingClientRect(),b=document.getElementById("guard-status").getBoundingClientRect();return a.bottom<=b.top||b.bottom<=a.top||a.right<=b.left||b.right<=a.left})()'),'cargo mission instructions must not overlap enemy status');assert.ok(await evaluate('(()=>{const a=document.getElementById("grenade-controls").getBoundingClientRect(),b=document.getElementById("announcement").getBoundingClientRect();return a.bottom<=b.top||b.bottom<=a.top||a.right<=b.left||b.right<=a.left})()'),'grenade controls must not cover the instruction line');await photo('campaign-cargo-phone-'+width);}await send('Emulation.setDeviceMetricsOverride',{width:1280,height:900,deviceScaleFactor:1,mobile:false});await send('Emulation.setTouchEmulationEnabled',{enabled:false});}
async function playCampaign(prefix:string){
 if(prefix.includes('export'))await campaignMobile();
 await evaluate('araPlay.game.enemies.forEach(e=>e.combat.health=0)');await keyboardRoute(await evaluate<any>('araPlay.game.pickups.find(p=>p.kind==="pistol")'),'pistol');await wait('araPlay.game.playerCombat.weapon==="pistol"','pistol collected');await keyboardRoute(await evaluate<any>('araPlay.game.world.checkpoints.cargo'),'briefcase');await press('KeyE');await wait('araPlay.game.hasCargo&&!araPlay.game.action','briefcase secured');assert.equal(await evaluate('araPlay.game.checkpoint.cargo'),true);await photo(prefix+'-briefcase');
 await evaluate('(()=>{const g=araPlay.game,e=g.enemies[0];g.protection=0;e.combat.health=100;Object.assign(e,{x:g.player.x,z:g.player.z,y:0,mode:"chase",awareness:1})})()');await wait('araPlay.game.status==="caught"','campaign loses one life');await click('#retry');await wait('araPlay.game.status==="playing"&&araPlay.game.hasCargo','cargo checkpoint retry');assert.ok(await evaluate('araPlay.game.remainingLives===2&&araPlay.game.playerCombat.weapon==="pistol"'));await evaluate('araPlay.game.enemies.forEach(e=>e.combat.health=0)');
 await keyboardRoute(await evaluate<any>('araPlay.game.world.checkpoints.key'),'depot key');await press('KeyE');await wait('araPlay.game.hasKey&&!araPlay.game.action','depot key acquired');await keyboardRoute(await evaluate<any>('araPlay.game.world.checkpoints.gate'),'depot gate');await press('KeyE');await wait('araPlay.game.door===1&&!araPlay.game.action','depot gate opened');await keyboardRoute(await evaluate<any>('araPlay.game.world.exit'),'depot extraction');await wait('araPlay.game.status==="won"','depot complete');assert.ok(await evaluate('araPlay.game.objectivesCompleted===4&&document.getElementById("retry").textContent.includes("Next mission")'));await photo(prefix+'-chapter-one');await click('#retry');await wait('araPlay.game.hub&&araPlay.game.status==="playing"','city hub');assert.ok(await evaluate('araPlay.game.hubFleet.length===araPlay.game.city.traffic&&araPlay.game.remainingLives===2'));await photo(prefix+'-city-hub');assert.ok(await evaluate('araPlay.scene.hubPeople.length===araPlay.game.city.pedestrians&&araPlay.scene.hubPeople.every(p=>p.render.character.params.detail==="low"&&p.render.character.params.top==="oversized_tee")&&[...araPlay.guards.values()].every(p=>p.render.character.params.top==="uniform_shirt")'));await evaluate('(()=>{const bike=araPlay.game.hubFleet.find(slot=>slot.model==="motorcycle"),p=araPlay.game.player,s=Math.sin(bike.car.yaw),c=Math.cos(bike.car.yaw),stand=bike.car.fit.stand;Object.assign(p,{x:bike.car.x+c*stand.x+s*stand.z,z:bike.car.z-s*stand.x+c*stand.z,y:0,grounded:true});})()');await press('KeyE');await wait('araPlay.game.car.phase==="driving"','motorcycle boarded');assert.ok(await evaluate('araPlay.game.vehicleSettings.model==="motorcycle"&&araPlay.scene.pickup.settings.model==="motorcycle"'));await photo(prefix+'-city-motorcycle');await evaluate('Object.assign(araPlay.game.car,araPlay.game.repairShop,{speed:0,health:50})');await wait('araPlay.game.repairShopNear','repair marker');await press('KeyE');await wait('araPlay.game.car.health===100','vehicle repaired');assert.ok(await evaluate('document.getElementById("score-status").textContent.includes("$0 cash")'));if(campaignCityOnly)return;await evaluate('Object.assign(araPlay.game.car,araPlay.game.world.exit,{speed:0})');await wait('araPlay.game.hubMissionReady','hub mission marker');await press('KeyE');await wait('araPlay.chapter===1&&araPlay.game.status==="playing"','next chapter launched');assert.ok(await evaluate('araPlay.game.remainingLives===2&&araPlay.game.playerCombat.weapon==="pistol"&&araPlay.chapterProject.loadout.weapon==="none"'));await photo(prefix+'-next-briefing');
 await send('Page.reload');await wait('window.araPlay&&!document.getElementById("start").disabled','campaign resume loads',120000);assert.ok(await evaluate('araPlay.chapter===1&&araPlay.game.remainingLives===2&&araPlay.game.playerCombat.weapon==="pistol"&&document.getElementById("load-label").textContent.includes("Resume")'));await click('#start');await evaluate('araPlay.game.enemies.forEach(e=>e.combat.health=0)');await keyboardRoute(await evaluate<any>('araPlay.game.world.rescue.approach'),'rescue captive');await press('KeyE');await wait('araPlay.game.companion.rescued&&!araPlay.game.action','Maya rescued');await keyboardRoute(driverStand(await evaluate<any>('araPlay.game.car')),'shared pickup');await press('KeyE');await wait('araPlay.game.readyToDrive','both aboard',45000);await driveCourseKeyboard(prefix);assert.ok(await evaluate('araPlay.game.routeStage===2&&araPlay.game.companion.riding.phase==="seated"&&document.getElementById("result-title").textContent==="Campaign complete."'));await photo(prefix+'-complete');
 await send('Page.reload');await wait('window.araPlay&&!document.getElementById("start").disabled','completed campaign reload',120000);assert.equal(await evaluate('document.getElementById("brief-title").textContent'),'Campaign complete.');await click('#start');assert.ok(await evaluate('araPlay.chapter===0&&araPlay.game.remainingLives===3&&araPlay.game.playerCombat.weapon==="none"&&!araPlay.game.hasCargo'));await press('Escape');
}
let checks=0;async function check(name:string,fn:()=>Promise<void>){if(filmsOnly&&!/builds two|films/.test(name))return;if(cityModesOnly&&!/builds two|city between|runner enemies/.test(name))return;if(arcadeOnly&&!/builds two|arcade/.test(name))return;if(studioFilmOnly&&!/builds two|Studio JSON film/.test(name))return;if(boardingUi&&!/builds two|boarding followup|mission context/.test(name))return;if(expansionOnly&&!/builds two|expansion/.test(name))return;if(accessOnly&&!/builds two|access setup|access gameplay/.test(name))return;if(coverOnly&&!/builds two|cover setup|cover gameplay/.test(name))return;if((campaignOnly||campaignExport)&&!/builds two|campaign gameplay|campaign setup|campaign export/.test(name))return;if(assistOnly&&!/builds two|assist setup|assist game/.test(name))return;if(rescueDrivingOnly&&!/builds two|rescue pickup/.test(name))return;if(missionVisualsOnly&&!/builds two|mission visuals/.test(name))return;if(drivingOnly&&!/builds two|pickup gameplay/.test(name))return;if(locationsOnly&&!/builds two|location scenarios/.test(name))return;if(grenadesOnly&&!/builds two|grenade gameplay/.test(name))return;if(exportOnly&&!/builds two|game export/.test(name))return;if(tiltOnly&&!/builds two|camera tilt/.test(name))return;if(presentationOnly&&!/builds two|presentation/.test(name))return;if(progressionOnly&&!/builds two|progression/.test(name))return;if(combatFeedbackOnly&&!/builds two|combat feedback/.test(name))return;if(rescueLayoutOnly&&!/builds two|rescue story retains/.test(name))return;if(rescueOnly&&!/builds two|rescue story/.test(name))return;if(combatOnly&&!/builds two|pistol combat|combat feedback/.test(name))return;if(recoveryOnly&&!/builds two|checkpoint retries/.test(name))return;if(mobileOnly&&!/builds two|customisable|saved setup/.test(name))return;if(traversalOnly&&!/builds two|contextual|abstract mission/.test(name))return;console.log('RUN',name);await fn();checks++;console.log('OK',name);}
