  await send('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile:true});await send('Emulation.setTouchEmulationEnabled',{enabled:true});await sleep(300);await evaluate('araPlay.scene.resetCamera(araPlay.game)');await sleep(150);const phoneBefore=await camera();await wait('!document.getElementById("combat-touch").hidden','phone combat controls');await click('#touch-aim',true);await stable(phoneBefore);await click('#touch-fire',true);await wait('araPlay.game.enemies[0].combat.health<66','touch bullet hits');assert.ok(await evaluate<number>(delta(guard))>.005,'touch hit also flinches');await stable(phoneBefore);await click('#touch-aim',true);await sleep(300);await stable(phoneBefore);await photo('mobile-combat-stable');
