  await send('Emulation.setTouchEmulationEnabled',{enabled:true});await send('Emulation.setDeviceMetricsOverride',{width:320,height:568,deviceScaleFactor:1,mobile:false});await send('Emulation.setPageScaleFactor',{pageScaleFactor:1});await press('KeyQ');await sleep(250);assert.equal(await evaluate('innerWidth'),320);
